class Solution:
    def maximumCount(self, banned: List[int], n: int, maxSum: int) -> int:
        b = set(banned)
        s = c = 0
        for i in range(1, n + 1):
            if i in b:
                continue
            if s + i > maxSum:
                break
            s += i
            c += 1
        return c

