class Solution {
public:
    int maximumCount(vector<int>& banned, int n, long long maxSum) {
        unordered_set<int> b(banned.begin(), banned.end());
        long long s = 0; int c = 0;
        for (long long i = 1; i <= n; i++) {
            if (b.count(i)) continue;
            if (s + i > maxSum) break;
            s += i; c++;
        }
        return c;
    }
};

