import bisect
class Solution:
    def maximumCount(self, banned: List[int], n: int, maxSum: int) -> int:
        banned.sort()
        pref = [0]
        for v in banned:
            pref.append(pref[-1] + v)
        def ok(x):
            if x == 0:
                return True
            v = x
            while True:
                b = bisect.bisect_right(banned, v)
                if x + b == v:
                    break
                v = x + b
            if v > n:
                return False
            return v * (v + 1) // 2 - pref[b] <= maxSum
        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if ok(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

