class Solution {
public:
    int maximumCount(vector<int>& banned, int n, long long maxSum) {
        sort(banned.begin(), banned.end());
        vector<long long> pref{0};
        for (int v : banned) pref.push_back(pref.back() + v);
        auto ok = [&](long long x) {
            if (x == 0) return true;
            long long v = x; long long b = 0;
            while (true) {
                b = upper_bound(banned.begin(), banned.end(), (int)min(v, (long long)INT_MAX)) - banned.begin();
                if (x + b == v) break;
                v = x + b;
            }
            if (v > n) return false;
            return v * (v + 1) / 2 - pref[b] <= maxSum;
        };
        long long lo = 0, hi = n;
        while (lo < hi) {
            long long mid = (lo + hi + 1) / 2;
            if (ok(mid)) lo = mid; else hi = mid - 1;
        }
        return (int)lo;
    }
};

