class Solution {
    public int maximumCount(int[] banned, int n, long maxSum) {
        Arrays.sort(banned);
        long[] pref = new long[banned.length + 1];
        for (int i = 0; i < banned.length; i++) pref[i + 1] = pref[i] + banned[i];
        for (int i = 1; i <= n; i++) {
            long v = i, b = 0;
            while (true) {
                b = upperBound(banned, (int) Math.min(v, Integer.MAX_VALUE));
                if (i + b == v) break;
                v = i + b;
            }
            if (v > n) continue;
            if (v * (v + 1) / 2 - pref[(int) b] <= maxSum) continue;
            return i - 1;
        }
        return n;
    }
    private int upperBound(int[] a, int x) {
        int lo = 0, hi = a.length;
        while (lo < hi) { int m = (lo + hi) >>> 1; if (a[m] <= x) lo = m + 1; else hi = m; }
        return lo;
    }
}

