var maximumCount = function(banned, n, maxSum) {
    banned.sort((a, b) => a - b);
    const pref = [0];
    for (const v of banned) pref.push(pref[pref.length - 1] + v);
    const ub = x => { let lo = 0, hi = banned.length; while (lo < hi) { const m = (lo + hi) >> 1; if (banned[m] <= x) lo = m + 1; else hi = m; } return lo; };
    for (let i = 1; i <= n; i++) {
        let v = i, b = 0;
        while (true) {
            b = ub(Math.min(v, Number.MAX_SAFE_INTEGER));
            if (i + b === v) break;
            v = i + b;
        }
        if (v > n) continue;
        if (v * (v + 1) / 2 - pref[b] <= maxSum) continue;
        return i - 1;
    }
    return n;
};
